64	bool NativePaddlePredictor::Init(
65	    std::shared_ptr<framework::Scope> parent_scope) {
66	  VLOG(3) << "Predictor::init()";
67	  if (FLAGS_profile) {
68	    LOG(WARNING) << "Profiler is actived, might affect the performance";
69	    LOG(INFO) << "You can turn off by set gflags '-profile false'";
70	
71	    auto tracking_device = config_.use_gpu ? platform::ProfilerState::kAll
72	                                           : platform::ProfilerState::kCPU;
73	    platform::EnableProfiler(tracking_device);
74	  }
75	
76	  // no matter with or without MKLDNN
77	  paddle::platform::SetNumThreads(config_.cpu_math_library_num_threads());
78	
79	  if (config_.use_gpu) {
80	    place_ = paddle::platform::CUDAPlace(config_.device);
81	  } else {
82	    place_ = paddle::platform::CPUPlace();
83	  }
84	  if (parent_scope) {
85	    scope_ = parent_scope;
86	    sub_scope_ = &(parent_scope->NewScope());
87	    PADDLE_ENFORCE_NOT_NULL(sub_scope_, "create sub scope fail");
88	  } else {
89	    paddle::framework::InitDevices(false);
90	    scope_.reset(new paddle::framework::Scope());
91	  }
92	
93	  executor_.reset(new paddle::framework::Executor(place_));
94	
95	  // Initialize the inference program
96	  if (!config_.model_dir.empty()) {
97	    // Parameters are saved in separate files sited in
98	    // the specified `dirname`.
99	    inference_program_ = paddle::inference::Load(executor_.get(), scope_.get(),
100	                                                 config_.model_dir);
101	  } else if (!config_.prog_file.empty() && !config_.param_file.empty()) {
102	    // All parameters are saved in a single file.
103	    // The file names should be consistent with that used
104	    // in Python API `fluid.io.save_inference_model`.
105	    inference_program_ = paddle::inference::Load(
106	        executor_.get(), scope_.get(), config_.prog_file, config_.param_file);
107	  } else {
108	    LOG(ERROR) << "fail to load inference model from " << config_.model_dir;
109	    return false;
110	  }
111	
112	  ctx_ = executor_->Prepare(*inference_program_, 0);
113	  executor_->CreateVariables(*inference_program_,
114	                             sub_scope_ ? sub_scope_ : scope_.get(), 0);
115	
116	  // Get the feed_target_names and fetch_target_names
117	  PrepareFeedFetch();
118	  return true;
119	}
