30	template <typename DeviceContext, typename T>
31	class SquaredL2DistanceKernel : public framework::OpKernel<T> {
32	 public:
33	  void Compute(const framework::ExecutionContext& context) const override {
34	    auto* in0 = context.Input<Tensor>("X");
35	    auto* in1 = context.Input<Tensor>("Y");
36	    auto* out0 = context.Output<Tensor>("sub_result");
37	    auto* out1 = context.Output<Tensor>("Out");
38	
39	    auto in0_dims = in0->dims();
40	    auto in1_dims = in1->dims();
41	
42	    int cols = in0->numel() / in0_dims[0];
43	    // reduce dimensions except the first
44	    auto x =
45	        EigenMatrix<T>::From(*in0, framework::make_ddim({in0_dims[0], cols}));
46	    auto y =
47	        EigenMatrix<T>::From(*in1, framework::make_ddim({in1_dims[0], cols}));
48	
49	    out0->mutable_data<T>(context.GetPlace());
50	    out1->mutable_data<T>(context.GetPlace());
51	    auto sub_result = EigenMatrix<T>::From(*out0);
52	    auto z = EigenVector<T>::Flatten(*out1);
53	
54	    auto& place =
55	        *context.template device_context<DeviceContext>().eigen_device();
56	    auto x_dims = x.dimensions();
57	    auto y_dims = y.dimensions();
58	    // buffer the substraction result
59	    if (y_dims[0] == 1 && x_dims[0] > y_dims[0]) {
60	      sub_result.device(place) =
61	          x -
62	          y.broadcast(Eigen::array<int, 2>({{static_cast<int>(x_dims[0]), 1}}));
63	    } else {
64	      sub_result.device(place) = x - y;
65	    }
66	    auto sub_res_pow2 = sub_result * sub_result;
67	    z.device(place) = sub_res_pow2.sum(Eigen::array<int, 1>({{1}}));
68	  }
69	};
