71	template <typename DeviceContext, typename T>
72	class SquaredL2DistanceGradKernel : public framework::OpKernel<T> {
73	 public:
74	  void Compute(const framework::ExecutionContext& context) const override {
75	    auto* in0 = context.Input<Tensor>("sub_result");
76	    auto* in1 = context.Input<Tensor>(framework::GradVarName("Out"));
77	    auto* x_g = context.Output<Tensor>(framework::GradVarName("X"));
78	    auto* y_g = context.Output<Tensor>(framework::GradVarName("Y"));
79	
80	    auto sub_result = EigenMatrix<T>::From(*in0);
81	    auto out_grad = EigenMatrix<T>::From(*in1);
82	
83	    auto x_dims = x_g->dims();
84	    auto y_dims = y_g->dims();
85	
86	    int cols = x_g->numel() / x_dims[0];
87	    // calculate gradient
88	    auto grad_mat = 2 *
89	                    (out_grad.broadcast(Eigen::array<int, 2>({{1, cols}}))) *
90	                    sub_result;
91	
92	    // propagate back to input
93	    auto& eigen_place =
94	        *context.template device_context<DeviceContext>().eigen_device();
95	    if (x_g) {
96	      x_g->mutable_data<T>(context.GetPlace());
97	      // eigen matrix
98	      auto x_grad =
99	          EigenMatrix<T>::From(*x_g, framework::make_ddim({x_dims[0], cols}));
100	      // dimensions are same with subResult
101	      x_grad.device(eigen_place) = grad_mat;
102	    }
103	
104	    if (y_g) {
105	      y_g->mutable_data<T>(context.GetPlace());
106	
107	      PADDLE_ENFORCE_GE(sub_result.dimensions()[0], y_dims[0],
108	                        "First dimension of gradient must be greater or "
109	                        "equal than first dimension of target.");
110	
111	      if (sub_result.dimensions()[0] == y_dims[0]) {
112	        auto y_grad =
113	            EigenMatrix<T>::From(*y_g, framework::make_ddim({y_dims[0], cols}));
114	        y_grad.device(eigen_place) = -1 * grad_mat;
115	      } else {
116	        auto col_sum_res = -1 * (grad_mat.sum(Eigen::array<int, 1>({{0}})));
117	        auto y_grad = EigenVector<T>::Flatten(*y_g);
118	        y_grad.device(eigen_place) = col_sum_res;
119	      }
120	    }
121	  }
122	};
